<?php elseif($page==='admin-access'):?><section class="panel"><div class="panel-head">Tenant-Leserechte pro Benutzer</div><div class="panel-body"><?php foreach($c->db->query('SELECT * FROM users WHERE is_global=0 ORDER BY username') as $account):$q=$c->db->prepare('SELECT tenant_id FROM tenant_access WHERE user_id=?');$q->execute([$account['id']]);$assigned=array_column($q->fetchAll(),'tenant_id');?><form method="post" action="/?page=tenant-access-save" style="padding-bottom:18px;border-bottom:1px solid var(--gray-700)"><input type="hidden" name="csrf" value="<?=h($c->csrf())?>"><input type="hidden" name="user" value="<?=h($account['id'])?>"><b><?=h($account['username'])?></b><?php foreach($tenants as $t):?><label style="font-weight:normal"><input style="width:auto" type="checkbox" name="tenants[]" value="<?=h($t['id'])?>" <?=in_array($t['id'],$assigned,true)?'checked':''?>> <?=h($t['name'])?></label><?php endforeach?><button class="small">Speichern</button></form><?php endforeach?></div></section><section class="panel"><div class="panel-head">Tenant-Leserechte pro Gruppe</div><div class="panel-body"><?php foreach($c->db->query('SELECT * FROM groups ORDER BY name') as $group):$q=$c->db->prepare('SELECT tenant_id FROM group_tenants WHERE group_id=?');$q->execute([$group['id']]);$assigned=array_column($q->fetchAll(),'tenant_id');?><form method="post" action="/?page=group-tenant-save" style="padding-bottom:18px;border-bottom:1px solid var(--gray-700)"><input type="hidden" name="csrf" value="<?=h($c->csrf())?>"><input type="hidden" name="group" value="<?=h($group['id'])?>"><b><?=h($group['name'])?></b><?php foreach($tenants as $t):?><label style="font-weight:normal"><input style="width:auto" type="checkbox" name="tenants[]" value="<?=h($t['id'])?>" <?=in_array($t['id'],$assigned,true)?'checked':''?>> <?=h($t['name'])?></label><?php endforeach?><button class="small">Speichern</button></form><?php endforeach?></div></section><section class="panel"><div class="panel-head">Benutzer zu Gruppe hinzufügen</div><div class="panel-body"><form method="post" action="/?page=group-member-add"><input type="hidden" name="csrf" value="<?=h($c->csrf())?>"><div class="form-grid"><div><label>Benutzer</label><select name="user"><?php foreach($c->db->query('SELECT * FROM users WHERE is_global=0 ORDER BY username') as $a):?><option value="<?=h($a['id'])?>"><?=h($a['username'])?></option><?php endforeach?></select></div><div><label>Gruppe</label><select name="group"><?php foreach($c->db->query('SELECT * FROM groups ORDER BY name') as $g):?><option value="<?=h($g['id'])?>"><?=h($g['name'])?></option><?php endforeach?></select></div></div><button>Hinzufügen</button></form></div></section>
