<?php elseif($page==='admin-system'):$legacyFile=dirname(__DIR__).'/state/legacy-installations.json';$legacy=is_file($legacyFile)?json_decode((string)file_get_contents($legacyFile),true):[];?><section class="panel"><div class="panel-head">Installation</div><div class="panel-body"><p><b>Version:</b> <?=h(trim((string)file_get_contents(dirname(__DIR__).'/VERSION')))?></p><p><b>Verzeichnis:</b> <?=h(dirname(__DIR__))?></p></div></section><?php if($legacy):?><div class="warning"><b>Weitere oder ältere Installationen erkannt</b><p>Die Hinweise bleiben bestehen, bis die Installation entfernt wurde.</p></div><?php foreach($legacy as $l):?><section class="panel"><div class="panel-head"><?=h($l['path']??'Unbekannte Installation')?></div><div class="panel-body"><form method="post" action="/?page=legacy-remove" onsubmit="return confirm('Installation wirklich vollständig entfernen?')"><input type="hidden" name="csrf" value="<?=h($c->csrf())?>"><input type="hidden" name="path" value="<?=h($l['path']??'')?>"><label>Passwort des angemeldeten globalen Administrators</label><input type="password" name="password" required><button class="red">Installation entfernen</button></form></div></section><?php endforeach?><?php else:?><div class="success">Keine weitere WAMS-Installation erkannt.</div><?php endif?>
